// Keeps only the rows that celebrate today (workflow timezone) and have not
// been greeted yet this year. One output item per matching contact.
const rows = $input.all().map((i) => i.json);
const today = { year: $today.year, month: $today.month, day: $today.day };

// Turns one spreadsheet row into a normalized contact and decides whether the
// row celebrates today. Pure function: (row, today:{year,month,day}) -> result.
function parseSheetDate(v) {
  if (v === null || v === undefined || v === '') return null;
  // Google Sheets can hand a date over as a serial number (days since 1899-12-30).
  if (typeof v === 'number' && isFinite(v)) {
    const d = new Date(Math.round((v - 25569) * 86400000));
    return { y: d.getUTCFullYear(), m: d.getUTCMonth() + 1, d: d.getUTCDate() };
  }
  const s = String(v).trim();
  let m = /^(\d{4})-(\d{1,2})-(\d{1,2})/.exec(s); // ISO — the documented format
  if (m) return { y: +m[1], m: +m[2], d: +m[3] };
  m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(s); // M/D/YYYY — Sheets' US default
  if (m) return { y: +m[3], m: +m[1], d: +m[2] };
  const t = Date.parse(s); // last resort: "March 14, 1992"
  if (!isNaN(t)) {
    // Non-ISO date-only strings parse at LOCAL midnight — read them back with
    // local getters or every date shifts a day in non-UTC timezones.
    const d = new Date(t);
    return { y: d.getFullYear(), m: d.getMonth() + 1, d: d.getDate() };
  }
  return null;
}

function isLeapYear(y) {
  return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
}

function normalizeRow(row, today) {
  const get = (k) => {
    // Column names are matched case-insensitively so "name" and "Name" both work.
    const key = Object.keys(row).find((rk) => rk.trim().toLowerCase() === k);
    return key === undefined ? undefined : row[key];
  };
  const name = String(get('name') || '').trim();
  if (!name) return { match: false, reason: 'empty Name' };

  const date = parseSheetDate(get('date'));
  if (!date) return { match: false, reason: `unreadable Date "${get('date')}" (use YYYY-MM-DD)`, name };

  // Month-day match; Feb 29 contacts celebrate on Feb 28 in non-leap years.
  const leapShift =
    date.m === 2 && date.d === 29 && !isLeapYear(today.year) &&
    today.month === 2 && today.day === 28;
  if (!(date.m === today.month && date.d === today.day) && !leapShift) {
    return { match: false, reason: 'not today', name };
  }

  // Idempotency guard: never greet the same contact twice in one year.
  const lastSent = parseInt(String(get('lastsentyear') || '').trim(), 10);
  if (lastSent === today.year) return { match: false, reason: 'already sent this year', name };

  const type =
    String(get('type') || 'birthday').trim().toLowerCase() === 'anniversary'
      ? 'anniversary'
      : 'birthday';

  // Explicit Years column wins. Otherwise anniversaries count from the Date's
  // year; birthdays never auto-compute (revealing an age must be opt-in).
  let years = parseInt(String(get('years') || '').trim(), 10);
  if (!(years > 0)) {
    years =
      type === 'anniversary' && date.y > 1900 && date.y < today.year
        ? today.year - date.y
        : null;
  }

  return {
    match: true,
    contact: {
      name,
      type,
      years: years > 0 ? years : null,
      message: String(get('message') || '').trim(), // optional per-row override
      email: String(get('email') || '').trim(),
      rowNumber: Number(get('row_number')) || null,
      lastSentYearNew: today.year,
    },
  };
}

const out = [];
const skipped = [];
rows.forEach((row, i) => {
  const r = normalizeRow(row, today);
  if (r.match) {
    out.push({ json: r.contact, pairedItem: { item: i } });
  } else if (r.reason && r.reason !== 'not today' && r.reason !== 'already sent this year') {
    skipped.push('row ' + (row.row_number || i + 2) + ' (' + (r.name || '?') + '): ' + r.reason);
  }
});
if (skipped.length) console.log('Rows skipped with problems:\n' + skipped.join('\n'));
// No matches -> no items -> the rest of the workflow simply does not run today.
return out;

// Builds one Zvid project per contact. The design logic is identical to the
// tested builder in the template repo — edit carefully and keep fonts/margins.
const cfg = $('Config').first().json;

// Assembles the Zvid project for one contact. Design blended from the library's
// celebration examples: img-app-thank-you (palette, serif headline, heart,
// divider), apppersonal-community-milestone (scene rhythm, pill kicker, entrance
// animations, footer brand) and saas-milestone (badge pill accents).
function ordinal(n) {
  const s = ['th', 'st', 'nd', 'rd'];
  const v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
}

function escapeHtml(s) {
  return String(s).replace(/[&<>"']/g, (c) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  }[c]));
}

// The API's project-name pattern is strict ASCII: /^[a-zA-Z0-9_\- ]+$/.
// Greeting names are routinely non-ASCII, so sanitize hard and keep a fallback.
function sanitizeProjectName(s) {
  const clean = String(s).toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 120);
  return clean || 'greeting-video';
}

function hexRgb(hex) {
  const m = /^#?([0-9a-f]{6})$/i.exec(String(hex).trim());
  if (!m) return '255,255,255';
  const n = parseInt(m[1], 16);
  return `${(n >> 16) & 255},${(n >> 8) & 255},${n & 255}`;
}

// Conservative greedy word-wrap estimate (avgEm ~ average glyph width in em).
// Used only to pick font sizes and stack elements — real layout is done by the
// renderer; the estimate errs on "more lines" so nothing ever overlaps.
function estimateLines(text, fontSize, boxWidth, avgEm) {
  const avg = fontSize * avgEm;
  const words = String(text).split(/\s+/).filter(Boolean);
  let lines = 1;
  let cur = 0;
  for (const w of words) {
    const wpx = w.length * avg;
    if (cur > 0 && cur + avg * 0.5 + wpx > boxWidth) {
      lines += 1;
      cur = wpx;
    } else {
      cur += (cur > 0 ? avg * 0.5 : 0) + wpx;
    }
  }
  return lines;
}

// Largest size whose longest word still fits the box and whose wrap stays
// within maxLines. Returns { size, lines }.
function fitFont(text, sizes, boxWidth, maxLines, avgEm) {
  const longest = Math.max(...String(text).split(/\s+/).filter(Boolean).map((w) => w.length), 1);
  let last = null;
  for (const size of sizes) {
    last = { size, lines: estimateLines(text, size, boxWidth, avgEm) };
    if (longest * size * avgEm <= boxWidth && last.lines <= maxLines) return last;
  }
  return last;
}

function buildProject(cfg, contact) {
  const accent = cfg.accent || '#FF6F91';
  const accent2 = cfg.accent2 || '#FFB86B';
  const aRgb = hexRgb(accent);
  const a2Rgb = hexRgb(accent2);
  const bg = cfg.backgroundColor || '#1A0C11';
  const textPrimary = cfg.textPrimary || '#FBEDE9';
  const textMuted = cfg.textMuted || '#C29A97';
  const mutedRgb = hexRgb(textMuted);
  const headingFont = cfg.headingFont || 'Playfair Display';
  const bodyFont = cfg.bodyFont || 'Space Grotesk';
  const s1 = Number(cfg.scene1Seconds ?? 5.2);
  const s2 = Number(cfg.scene2Seconds ?? 5.6);
  const tDur = Number(cfg.transitionSeconds ?? 0.55);

  const name = String(contact.name || '').trim() || 'Friend';
  const type = contact.type === 'anniversary' ? 'anniversary' : 'birthday';
  const years = Number(contact.years) > 0 ? Math.round(Number(contact.years)) : null;
  const brandName = String(cfg.brandName || 'Zvid').trim();
  const signoff = String(cfg.signoffText || '').trim() || `— The ${brandName} Team`;

  const occasionLine =
    type === 'anniversary'
      ? years ? `Happy ${ordinal(years)} Anniversary` : 'Happy Anniversary'
      : years ? `Happy ${ordinal(years)} Birthday` : 'Happy Birthday';

  // Message: per-row override > per-occasion config default. {brand}/{name}/{years}
  // tokens personalise the config defaults.
  const rawMessage =
    String(contact.message || '').trim() ||
    String((type === 'anniversary' ? cfg.anniversaryMessage : cfg.birthdayMessage) || '').trim() ||
    'Wishing you a wonderful day and an even better year ahead.';
  const message = rawMessage
    .replace(/\{brand\}/g, brandName)
    .replace(/\{name\}/g, name.split(/\s+/)[0])
    .replace(/\{years\}/g, years ? String(years) : 'many');

  // ---- background + ornament SVGs ---------------------------------------
  const frame = `<rect x='40' y='40' width='1000' height='1840' rx='46' fill='none' stroke='#FFFFFF' stroke-opacity='0.08' stroke-width='1.5'/>`;
  const sparkle = (x, y, r, o) =>
    `<circle cx='${x}' cy='${y}' r='${r}' fill='${accent2}' fill-opacity='${o}'/>`;
  const sparkles =
    sparkle(150, 320, 5, 0.35) + sparkle(930, 420, 4, 0.3) + sparkle(210, 1520, 4, 0.25) +
    sparkle(880, 1460, 6, 0.3) + sparkle(540, 210, 3, 0.3) + sparkle(120, 980, 3, 0.22) +
    sparkle(960, 1040, 3, 0.22);
  const bgSvg = (cx, cy) =>
    `<svg width='1080' height='1920' viewBox='0 0 1080 1920' xmlns='http://www.w3.org/2000/svg'><defs>` +
    `<radialGradient id='ga' cx='${cx}' cy='${cy}' r='0.75'><stop offset='0' stop-color='${accent}' stop-opacity='0.34'/><stop offset='1' stop-color='${accent}' stop-opacity='0'/></radialGradient>` +
    `<radialGradient id='gb' cx='0.15' cy='0.92' r='0.7'><stop offset='0' stop-color='${accent2}' stop-opacity='0.2'/><stop offset='1' stop-color='${accent2}' stop-opacity='0'/></radialGradient>` +
    `<linearGradient id='gd' x1='0' y1='0' x2='0' y2='1'><stop offset='0.55' stop-color='#000000' stop-opacity='0'/><stop offset='1' stop-color='#000000' stop-opacity='0.4'/></linearGradient>` +
    `</defs><rect width='1080' height='1920' fill='${bg}'/><rect width='1080' height='1920' fill='url(#ga)'/><rect width='1080' height='1920' fill='url(#gb)'/><rect width='1080' height='1920' fill='url(#gd)'/>${sparkles}${frame}</svg>`;

  // Gradient heart from img-app-thank-you (translated into a 300x280 box);
  // anniversaries get the ring treatment from the community-milestone thanks scene.
  const heartHalo = `<radialGradient id='hh' cx='0.5' cy='0.5' r='0.5'><stop offset='0.6' stop-color='${accent}' stop-opacity='0'/><stop offset='1' stop-color='${accent}' stop-opacity='0.28'/></radialGradient>`;
  const heartGrad = `<linearGradient id='ht' x1='0' y1='0' x2='1' y2='1'><stop offset='0' stop-color='${accent2}'/><stop offset='1' stop-color='${accent}'/></linearGradient>`;
  const iconSvg =
    type === 'anniversary'
      ? `<svg width='300' height='280' viewBox='0 0 300 280' xmlns='http://www.w3.org/2000/svg'><defs>${heartHalo}${heartGrad}</defs>` +
        `<circle cx='150' cy='140' r='134' fill='url(#hh)'/>` +
        `<circle cx='150' cy='140' r='118' fill='none' stroke='rgba(${a2Rgb},0.7)' stroke-width='3'/>` +
        `<path d='M150 208.8 C70 156 78 87.2 127.6 87.2 C146.8 87.2 150 111.2 150 111.2 C150 111.2 153.2 87.2 172.4 87.2 C222 87.2 230 156 150 208.8 Z' fill='url(#ht)'/></svg>`
      : `<svg width='300' height='280' viewBox='0 0 300 280' xmlns='http://www.w3.org/2000/svg'><defs>${heartHalo}${heartGrad}</defs>` +
        `<circle cx='150' cy='140' r='134' fill='url(#hh)'/>` +
        `<path d='M150 226 C50 160 60 74 122 74 C146 74 150 104 150 104 C150 104 154 74 178 74 C240 74 250 160 150 226 Z' fill='url(#ht)'/></svg>`;

  const dividerSvg =
    `<svg width='100' height='20' viewBox='0 0 100 20' xmlns='http://www.w3.org/2000/svg'>` +
    `<line x1='0' y1='10' x2='38' y2='10' stroke='${accent}' stroke-opacity='0.6' stroke-width='1.4'/>` +
    `<line x1='62' y1='10' x2='100' y2='10' stroke='${accent}' stroke-opacity='0.6' stroke-width='1.4'/>` +
    `<circle cx='50' cy='10' r='4' fill='${accent}'/></svg>`;

  // Soft bokeh lights drifting upward — negative delays put every light
  // mid-flight on frame one, so nothing "pops in" at the start of a scene.
  const bokeh = (seconds) => ({
    animationDuration: Math.min(15, seconds),
    css:
      `.fx{position:relative;width:1080px;height:1920px;overflow:hidden}` +
      `.fx i{position:absolute;bottom:-220px;display:block;border-radius:50%;animation:rise 9s linear infinite}` +
      `.fx i:nth-child(1){left:6%;width:150px;height:150px;background:radial-gradient(circle,rgba(${aRgb},0.4) 0%,rgba(${aRgb},0) 70%);animation-delay:-1.5s}` +
      `.fx i:nth-child(2){left:78%;width:110px;height:110px;background:radial-gradient(circle,rgba(${a2Rgb},0.38) 0%,rgba(${a2Rgb},0) 70%);animation-delay:-4s;animation-duration:11s}` +
      `.fx i:nth-child(3){left:30%;width:80px;height:80px;background:radial-gradient(circle,rgba(${a2Rgb},0.32) 0%,rgba(${a2Rgb},0) 70%);animation-delay:-7s;animation-duration:8s}` +
      `.fx i:nth-child(4){left:58%;width:180px;height:180px;background:radial-gradient(circle,rgba(${aRgb},0.3) 0%,rgba(${aRgb},0) 70%);animation-delay:-6s;animation-duration:13s}` +
      `.fx i:nth-child(5){left:14%;width:90px;height:90px;background:radial-gradient(circle,rgba(${aRgb},0.34) 0%,rgba(${aRgb},0) 70%);animation-delay:-3s;animation-duration:10s}` +
      `.fx i:nth-child(6){left:88%;width:70px;height:70px;background:radial-gradient(circle,rgba(${a2Rgb},0.3) 0%,rgba(${a2Rgb},0) 70%);animation-delay:-8s;animation-duration:9s}` +
      `@keyframes rise{0%{transform:translateY(0);opacity:0}12%{opacity:.75}75%{opacity:.4}100%{transform:translateY(-2100px);opacity:0}}`,
  });
  const bokehVisual = (seconds) => ({
    type: 'TEXT',
    html: `<div class='fx'><i></i><i></i><i></i><i></i><i></i><i></i></div>`,
    x: 540, y: 960, anchor: 'center-center',
    track: 1, opacity: 0.55,
    enterBegin: 0, exitEnd: seconds,
    style: { fontFamily: bodyFont, color: textPrimary },
    customCode: bokeh(seconds),
  });

  // ---- scene 1: the reveal ----------------------------------------------
  const nameFit = fitFont(name, [132, 116, 100, 84, 72, 64], 940, 2, 0.56);
  const nameH = Math.ceil(nameFit.lines * nameFit.size * 1.12);
  const dividerY = 860 + nameH + 80;
  const chipY = dividerY + 90;
  const chipLine = type === 'anniversary' && years ? `Celebrating ${years} wonderful years` : null;

  const scene1 = {
    id: 'reveal',
    duration: s1,
    backgroundColor: bg,
    transition: 'fade',
    transitionId: 'message',
    transitionDuration: tDur,
    visuals: [
      { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: s1, svg: bgSvg(0.5, 0.24) },
      bokehVisual(s1),
      {
        type: 'SVG', x: 390, y: 380, width: 300, height: 280, anchor: 'top-left',
        track: 2, enterBegin: 0.15, enterEnd: 0.6, enterAnimation: 'fade', exitEnd: s1,
        svg: iconSvg,
      },
      {
        type: 'TEXT', x: 540, y: 740, anchor: 'top-center',
        track: 3, enterBegin: 0.3, enterEnd: 0.75, enterAnimation: 'fade', exitEnd: s1,
        style: { fontFamily: bodyFont, color: accent2 },
        html: `<div style='display:inline-block; background:rgba(${a2Rgb},0.1); border:1.5px solid rgba(${a2Rgb},0.55); color:${accent2}; border-radius:999px; padding:14px 40px; font-size:26px; font-weight:800; letter-spacing:6px;'>${escapeHtml(occasionLine.toUpperCase())}</div>`,
      },
      {
        type: 'TEXT', x: 70, y: 860, width: 940, anchor: 'top-left',
        track: 4, enterBegin: 0.55, enterEnd: 1.05, enterAnimation: 'circleopen', exitEnd: s1,
        style: { fontFamily: headingFont, color: textPrimary },
        html: `<div style='text-align:center; color:${textPrimary}; font-size:${nameFit.size}px; line-height:1.12; font-weight:700; letter-spacing:-1px;'>${escapeHtml(name)}</div>`,
      },
      {
        type: 'SVG', x: 490, y: dividerY, width: 100, height: 20, anchor: 'top-left',
        track: 5, enterBegin: 0.95, enterEnd: 1.35, enterAnimation: 'fade', exitEnd: s1,
        svg: dividerSvg,
      },
      ...(chipLine
        ? [{
            type: 'TEXT', x: 540, y: chipY, anchor: 'top-center',
            track: 6, enterBegin: 1.15, enterEnd: 1.6, enterAnimation: 'smoothup', exitEnd: s1,
            style: { fontFamily: bodyFont, color: accent },
            html: `<div style='display:inline-block; background:rgba(${aRgb},0.14); border:1.5px solid rgba(${aRgb},0.5); color:${accent}; border-radius:999px; padding:16px 40px; font-size:32px; font-weight:700;'>${escapeHtml(chipLine)}</div>`,
          }]
        : []),
      {
        type: 'TEXT', x: 540, y: 1700, anchor: 'top-center',
        track: 7, enterBegin: 1.3, enterEnd: 1.7, enterAnimation: 'fade', exitEnd: s1,
        style: { fontFamily: bodyFont, color: textMuted },
        html: `<div style='text-align:center; color:rgba(${mutedRgb},0.7); font-size:26px; font-weight:700; letter-spacing:5px;'>${escapeHtml(brandName.toUpperCase())}</div>`,
      },
    ],
  };

  // ---- scene 2: the message ---------------------------------------------
  const msgFit = fitFont(message, [42, 38, 34, 30], 800, 8, 0.5);
  const msgH = Math.ceil(msgFit.lines * msgFit.size * 1.55);
  const msgTop = Math.max(620, Math.min(900, Math.round(990 - (msgH + 230) / 2)));
  const divider2Y = msgTop + msgH + 90;
  const signoffY = divider2Y + 100;
  const heart2Y = msgTop - 260; // keeps a fixed beat between the heart and the copy

  const smallHeart =
    `<svg width='140' height='130' viewBox='0 0 240 220' xmlns='http://www.w3.org/2000/svg'><defs>${heartGrad}</defs>` +
    `<path d='M120 196 C20 130 30 44 92 44 C116 44 120 74 120 74 C120 74 124 44 148 44 C210 44 220 130 120 196 Z' fill='url(#ht)'/></svg>`;

  const scene2 = {
    id: 'message',
    duration: s2,
    backgroundColor: bg,
    visuals: [
      { type: 'SVG', width: 1080, height: 1920, track: 0, enterBegin: 0, exitEnd: s2, svg: bgSvg(0.5, 0.4) },
      bokehVisual(s2),
      {
        type: 'SVG', x: 470, y: heart2Y, width: 140, height: 130, anchor: 'top-left',
        track: 2, enterBegin: 0.15, enterEnd: 0.55, enterAnimation: 'fade', exitEnd: s2,
        svg: smallHeart,
      },
      {
        type: 'TEXT', x: 140, y: msgTop, width: 800, anchor: 'top-left',
        track: 3, enterBegin: 0.35, enterEnd: 0.85, enterAnimation: 'smoothup', exitEnd: s2,
        text: message,
        style: { fontFamily: bodyFont, fontSize: `${msgFit.size}px`, fontWeight: '400', lineHeight: '1.55', color: textMuted, textAlign: 'center' },
      },
      {
        type: 'SVG', x: 490, y: divider2Y, width: 100, height: 20, anchor: 'top-left',
        track: 4, enterBegin: 0.75, enterEnd: 1.15, enterAnimation: 'fade', exitEnd: s2,
        svg: dividerSvg,
      },
      {
        type: 'TEXT', x: 90, y: signoffY, width: 900, anchor: 'top-left',
        track: 5, enterBegin: 0.95, enterEnd: 1.4, enterAnimation: 'fade', exitEnd: s2,
        text: signoff,
        style: { fontFamily: headingFont, fontSize: '46px', fontWeight: '500', fontStyle: 'italic', color: textPrimary, textAlign: 'center' },
      },
      {
        type: 'TEXT', x: 540, y: 1700, anchor: 'top-center',
        track: 6, enterBegin: 0.2, enterEnd: 0.6, enterAnimation: 'fade', exitEnd: s2,
        style: { fontFamily: bodyFont, color: textMuted },
        html: `<div style='text-align:center; color:rgba(${mutedRgb},0.7); font-size:26px; font-weight:700; letter-spacing:5px;'>${escapeHtml(brandName.toUpperCase())}</div>`,
      },
    ],
  };

  const totalSeconds = Math.round((s1 + s2 - tDur) * 100) / 100;
  const projectName = sanitizeProjectName(`${occasionLine} - ${name}`);
  const firstName = name.split(/\s+/)[0];

  const payload = {
    name: projectName,
    resolution: cfg.resolution || 'instagram-reel',
    frameRate: Number(cfg.frameRate ?? 30),
    backgroundColor: bg,
    outputFormat: 'mp4',
    scenes: [scene1, scene2],
    ...(cfg.musicUrl
      ? { audios: [{ src: cfg.musicUrl, volume: Number(cfg.musicVolume ?? 0.18) }] }
      : {}),
  };

  return {
    payload,
    meta: {
      contactName: name,
      firstName,
      type,
      years,
      occasionLine,
      projectName,
      totalSeconds,
      emailSubject: `${occasionLine}, ${firstName}!`,
      email: contact.email || null,
      rowNumber: contact.rowNumber ?? null,
      lastSentYearNew: contact.lastSentYearNew ?? null,
    },
  };
}

return $input.all().map((item, i) => {
  const { payload, meta } = buildProject(cfg, item.json);
  return { json: { payload, meta }, pairedItem: { item: i } };
});

// The free validate endpoint runs the exact pipeline a render submission runs,
// so a failure here is a payload bug — surface the field list per contact
// instead of a generic HTTP error.
const built = $('Build project JSON').all();
return $input.all().map((res, i) => {
  const status = res.json.statusCode;
  const body = res.json.body || {};
  const meta = built[i].json.meta;
  if (status !== 200 || body.valid === false) {
    const details = Array.isArray(body.details)
      ? body.details.map((d) => '  - ' + d.field + ': ' + d.message).join('\n')
      : JSON.stringify(body).slice(0, 500);
    throw new Error('Zvid rejected the greeting for ' + meta.contactName + ' (HTTP ' + status + '): ' + (body.message || body.error) + '\n' + details);
  }
  return {
    json: { ...built[i].json, creditsRequired: body.creditsRequired, warnings: body.warnings || [] },
    pairedItem: { item: i },
  };
});

// The render response replaces the item, so glue the jobId back onto the
// contact. An index zip is safe here: same items, same order, no loop yet.
const checked = $('Check validation').all();
return $input.all().map((res, i) => {
  const jobId = res.json.jobId || res.json.id;
  if (!jobId) {
    throw new Error('Render submission returned no jobId: ' + JSON.stringify(res.json).slice(0, 300));
  }
  const { payload, ...rest } = checked[i].json;
  return { json: { ...rest, jobId }, pairedItem: { item: i } };
});

// The status response replaces the item again — zip it back with what entered
// this poll iteration. Wait passes items through unchanged and the status node
// runs once per item in order, so index i pairs correctly on every lap.
const carried = $('Wait').all();
return $input.all().map((res, i) => {
  const job = res.json;
  return {
    json: {
      ...carried[i].json,
      state: job.state,
      failedReason: job.failedReason || null,
      result: job.result || null,
    },
    pairedItem: { item: i },
  };
});

// Fails fast on a failed render and stops the poll loop at the timeout.
// Nothing has been written back to the sheet yet, so a failed run retries the
// same contacts tomorrow — no greeting is ever silently dropped.
const cfg = $('Config').first().json;
for (const item of $input.all()) {
  if (item.json.state === 'failed') {
    throw new Error('Render failed for ' + item.json.meta.contactName + ': ' + (item.json.failedReason || 'no reason given') + '. LastSentYear was not written, so the next run retries this contact.');
  }
}
const maxPolls = Math.ceil((Number(cfg.timeoutMinutes || 20) * 60) / Number(cfg.pollSeconds || 10));
if ($runIndex + 1 >= maxPolls) {
  throw new Error('Render did not finish within ' + cfg.timeoutMinutes + ' minutes.');
}
return $input.all();

// Composes the per-contact delivery: the finished video URL plus a short,
// warm HTML email that matches the video's palette.
const cfg = $('Config').first().json;
const d = $json;
const videoUrl = typeof d.result === 'string' ? d.result : (d.result && d.result.url) || null;
if (!videoUrl) {
  throw new Error('Completed render returned no video URL for ' + d.meta.contactName);
}
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const brand = String(cfg.brandName || 'our team');
const signoff = String(cfg.signoffText || '').trim() || ('— The ' + brand + ' Team');
const emailHtml =
  '<div style="font-family:Georgia,serif; background:' + (cfg.backgroundColor || '#1A0C11') + '; color:' + (cfg.textPrimary || '#FBEDE9') + '; padding:40px 32px; border-radius:16px; max-width:560px; margin:auto; text-align:center;">' +
  '<p style="letter-spacing:4px; color:' + (cfg.accent2 || '#FFB86B') + '; font-size:13px; margin:0 0 14px; text-transform:uppercase;">' + esc(d.meta.occasionLine) + '</p>' +
  '<h1 style="font-size:30px; margin:0 0 18px; font-weight:700;">' + esc(d.meta.contactName) + '</h1>' +
  '<p style="color:' + (cfg.textMuted || '#C29A97') + '; font-size:15px; line-height:1.6; margin:0 0 28px;">We made you a little something — press play.</p>' +
  '<a href="' + videoUrl + '" style="display:inline-block; background:' + (cfg.accent || '#FF6F91') + '; color:' + (cfg.backgroundColor || '#1A0C11') + '; font-weight:bold; padding:14px 36px; border-radius:999px; text-decoration:none;">Watch your video</a>' +
  '<p style="color:' + (cfg.textMuted || '#C29A97') + '; font-size:13px; margin:28px 0 0; font-style:italic;">' + esc(signoff) + '</p>' +
  '</div>';
return {
  json: {
    contact: d.meta.contactName,
    occasion: d.meta.occasionLine,
    email: d.meta.email || null,
    rowNumber: d.meta.rowNumber,
    lastSentYearNew: d.meta.lastSentYearNew,
    videoUrl,
    jobId: d.jobId,
    creditsCharged: d.creditsRequired,
    emailSubject: d.meta.emailSubject,
    emailHtml,
  },
};

// Final per-contact report for the run.
const cfg = $('Config').first().json;
const d = $('Prepare delivery').item.json;
return {
  json: {
    sent: true,
    contact: d.contact,
    occasion: d.occasion,
    videoUrl: d.videoUrl,
    jobId: d.jobId,
    creditsCharged: d.creditsCharged,
    emailSent: Boolean(cfg.sendEmail) && String(d.email || '').includes('@'),
    emailTo: d.email || null,
    lastSentYearWritten: d.lastSentYearNew,
  },
};

// Dry run: everything except the paid render. Open editorLink to preview each
// greeting, then set dryRun to false in Config to render and deliver for real.
const cfg = $('Config').first().json;
const checked = $('Check validation').all();
return $input.all().map((res, i) => {
  const d = checked[i].json;
  let editorLink = null;
  let draftId = null;
  const project = res.json && res.json.project;
  if (project && project.id) {
    draftId = project.id;
    editorLink = String(cfg.editorUrl || 'https://editor.zvid.io').replace(/\/+$/, '') + '/?project=' + project.id;
  }
  return {
    json: {
      dryRun: true,
      contact: d.meta.contactName,
      occasion: d.meta.occasionLine,
      email: d.meta.email || null,
      creditsRequired: d.creditsRequired,
      videoSeconds: d.meta.totalSeconds,
      editorLink,
      draftId,
      warnings: d.warnings,
      nextStep: editorLink
        ? 'Open editorLink to preview this greeting. Set dryRun to false in Config to render and deliver.'
        : 'Set dryRun to false in Config to render and deliver this greeting.',
      payload: d.payload,
    },
    pairedItem: { item: i },
  };
});
